using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

/// <summary>
/// Editor tool that disables shadow casting on all MeshRenderers
/// found inside the currently selected prefab assets.
/// </summary>
public static class DisableShadowsForSelectedPrefabs
{
    [MenuItem("Assets/Optimizations/Disable shadows for selected prefabs", true)]
    private static bool ValidateDisableShadows()
    {
        // Only enable the menu item if at least one selected object is a prefab asset.
        foreach (var obj in Selection.gameObjects)
        {
            if (PrefabUtility.GetPrefabAssetType(obj) != PrefabAssetType.NotAPrefab)
                return true;
        }
        return false;
    }

    [MenuItem("Assets/Optimizations/Disable shadows for selected prefabs")]
    private static void DisableShadows()
    {
        GameObject[] selectedPrefabs = Selection.gameObjects;
        int modifiedPrefabCount = 0;
        int modifiedRendererCount = 0;

        // Suspends automatic reimporting while we modify prefabs, so dependent assets
        // (nested prefabs, prefab variants) get reimported once in a batch at
        // StopAssetEditing() instead of after every single SaveAsPrefabAsset call.
        AssetDatabase.StartAssetEditing();

        try
        {
            for (int i = 0; i < selectedPrefabs.Length; i++)
            {
                GameObject selected = selectedPrefabs[i];

                if (PrefabUtility.GetPrefabAssetType(selected) == PrefabAssetType.NotAPrefab)
                    continue;

                string assetPath = AssetDatabase.GetAssetPath(selected);
                if (string.IsNullOrEmpty(assetPath))
                    continue;

                EditorUtility.DisplayProgressBar(
                    "Disabling shadows",
                    $"Processing {assetPath}",
                    (float)i / selectedPrefabs.Length);

                // Load an editable, isolated copy of the prefab's contents.
                GameObject prefabRoot = PrefabUtility.LoadPrefabContents(assetPath);
                bool prefabChanged = false;

                try
                {
                    MeshRenderer[] renderers = prefabRoot.GetComponentsInChildren<MeshRenderer>(true);
                    foreach (MeshRenderer renderer in renderers)
                    {
                        if (renderer.shadowCastingMode != ShadowCastingMode.Off)
                        {
                            renderer.shadowCastingMode = ShadowCastingMode.Off;
                            modifiedRendererCount++;
                            prefabChanged = true;
                        }
                    }

                    if (prefabChanged)
                    {
                        PrefabUtility.SaveAsPrefabAsset(prefabRoot, assetPath);
                        modifiedPrefabCount++;
                    }
                }
                finally
                {
                    // Always unload, even if something above threw.
                    PrefabUtility.UnloadPrefabContents(prefabRoot);
                }
            }
        }
        finally
        {
            AssetDatabase.StopAssetEditing();
            EditorUtility.ClearProgressBar();
        }

        AssetDatabase.SaveAssets();

        Debug.Log($"Disable shadows: modified {modifiedRendererCount} MeshRenderer(s) " +
                  $"across {modifiedPrefabCount} prefab(s).");
    }
}